use retailproj;
select *
from customer_shopping;

-- Q1. What is the total revenue generated by male vs. female customers?
select gender,sum(purchase_amount) as Revenue
from customer_shopping
group by gender ;

-- Q2. Which customers used a discount but still spent more than the average purchase amount?
select customer_id,age,purchase_amount
from customer_shopping
where discount_applied ="yes" and purchase_amount > (select avg(purchase_amount) from customer_shopping);

-- Q3. Which are the top 5 products with the highest average review rating?
select item_purchased,round(avg(review_rating),2) as "Avg Product Review"
from customer_shopping
group by item_purchased
order by avg(review_rating) desc
limit 10;


-- Q4. Compare the average Purchase Amounts between Standard and Express Shipping.
select round(avg(purchase_amount),2),shipping_type
from customer_shopping
where shipping_type in ("Standard","Express")
group by shipping_type;

-- Q5. Do subscribed customers spend more? Compare average spend and total revenue between 
-- subscribers and non-subscribers.
select subscription_status,count(customer_id) as "Total customer",
avg(purchase_amount) as "Avg spend",sum(purchase_amount) as "Total Revenue"
from customer_shopping
where subscription_status in ("Yes","No")
group by subscription_status
limit 10;


-- Q6. Which 5 products have the highest percentage of purchases with discounts applied?
select item_purchased, sum(case when discount_applied = "yes" then 1 else 0 end)/count(*)*100 as Percentage_discount_applied
from customer_shopping
group by item_purchased
order by percentage_discount_applied desc
limit 5;



-- Q7. Segment customers into New, Returning, and Loyal based on their total number of  
-- previous purchases, and show the count of each segment

with customer_segment as (
select customer_id,previous_purchases,
case 
  when previous_purchases = 1 then 'New'
  when previous_purchases between 2 and 10 then 'Returning'
  else 'Loyal'
  end as customer_type
from customer_shopping
)
select customer_type,count(*) 'Total_customer'
from customer_segment
group by customer_type;

