-- Q8. What are the top 3 most purchased products within each category?

with RankedItems as (
select category,item_purchased,count(*) as Total_purchases,
Row_number() over(partition by category order by count(*) desc) as item_rank
from customer_shopping
group by category,item_purchased
)
select category,item_purchased,total_purchases
from RankedItems
where item_rank <= 3;

-- are customer who are repeat buyer(more the  5 previous purchases) also likely to subscribe ?
select subscription_status,count(customer_id) as Repeat_customer
from customer_shopping
where previous_purchases > 5
group by subscription_status;


-- what is the revenue contibution of each age group?
select age_category as Age_Group ,sum(purchase_amount) as Total_Revenue
from customer_shopping
group by age_category
order by sum(purchase_amount) desc;